components.css:
.ds-action { position: relative; display: inline-flex; width: fit-content; align-items: flex-end; gap: 12px; padding: 14px 0 10px; text-decoration: none; color: var(--color-bone-2, #a5a29b); transition: color 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-action--primary { color: var(--color-bone, #f2f0eb); }
.ds-action__label { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: 0.8125rem; font-weight: 500; line-height: 1.5; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-action__head { margin-bottom: 0.2em; height: 0.6em; width: 0.85em; flex-shrink: 0; fill: currentColor; transition: transform 400ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-action__rest { position: absolute; inset-inline: 0; bottom: 0; height: 1px; background: var(--color-rule, #2e2f33); }
.ds-action--primary .ds-action__rest { background: color-mix(in srgb, var(--color-bone, #f2f0eb) 40%, transparent); }
.ds-action__draw { position: absolute; bottom: 0; left: 0; height: 1px; width: 100%; transform: scaleX(0); transform-origin: left; background: var(--color-bone, #f2f0eb); transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-action:hover, .ds-action:focus-visible { color: var(--color-bone, #f2f0eb); }
.ds-action:hover .ds-action__head, .ds-action:focus-visible .ds-action__head { transform: translateX(4px); }
.ds-action:hover .ds-action__draw, .ds-action:focus-visible .ds-action__draw { transform: scaleX(1); }
.ds-action:focus-visible { outline: 1px solid var(--color-bone, #f2f0eb); outline-offset: 3px; }

.ds-action { position: relative; display: inline-flex; width: fit-content; align-items: flex-end; gap: 12px; padding: 14px 0 10px; text-decoration: none; color: var(--color-bone-2, #a5a29b); transition: color 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-action__label { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: 0.8125rem; font-weight: 500; line-height: 1.5; letter-spacing: 0.14em; text-transform: uppercase; }
.ds-action__head { margin-bottom: 0.2em; height: 0.6em; width: 0.85em; flex-shrink: 0; fill: currentColor; transition: transform 400ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-action__rest { position: absolute; inset-inline: 0; bottom: 0; height: 1px; background: var(--color-rule, #2e2f33); }
.ds-action__draw { position: absolute; bottom: 0; left: 0; height: 1px; width: 100%; transform: scaleX(0); transform-origin: left; background: var(--color-bone, #f2f0eb); transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-action:hover, .ds-action:focus-visible { color: var(--color-bone, #f2f0eb); }
.ds-action:hover .ds-action__head, .ds-action:focus-visible .ds-action__head { transform: translateX(4px); }
.ds-action:hover .ds-action__draw, .ds-action:focus-visible .ds-action__draw { transform: scaleX(1); }

.ds-rail { width: fit-content; }
.ds-rail__list { display: flex; flex-direction: column; margin: 0; padding: 0; list-style: none; }
.ds-rail__item { display: flex; align-items: center; gap: 12px; padding: 10px 0; text-decoration: none; }
.ds-rail__mark { position: relative; display: block; height: 3px; width: 28px; flex-shrink: 0; }
.ds-rail__track { position: absolute; inset-inline: 0; top: 1px; display: block; height: 1px; background: var(--color-rule, #2e2f33); }
.ds-rail__pen { position: absolute; top: 0; left: 0; display: block; height: 3px; width: 0; background: var(--color-bone, #f2f0eb); transition: width 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-rail__item.is-active .ds-rail__pen { width: 100%; }
.ds-rail__num { font-family: 'Martian Mono', ui-monospace, 'Cascadia Mono', monospace; font-size: 0.625rem; font-weight: 500; line-height: 1.4; letter-spacing: 0.08em; text-transform: uppercase; font-variant-numeric: tabular-nums; color: var(--color-bone-3, #8a8782); transition: color 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-rail__name { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: 0.6875rem; font-weight: 500; line-height: 1.5; letter-spacing: 0.1em; text-transform: uppercase; color: var(--color-bone-3, #8a8782); transition: color 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-rail__item.is-active .ds-rail__num, .ds-rail__item.is-active .ds-rail__name { color: var(--color-bone, #f2f0eb); }
.ds-rail__item:hover .ds-rail__num, .ds-rail__item:hover .ds-rail__name { color: var(--color-bone-2, #a5a29b); }
.ds-rail__block { margin-top: 24px; display: flex; width: fit-content; flex-direction: column; border-top: 1px solid var(--color-rule, #2e2f33); padding-top: 12px; }
.ds-rail__action { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: 0.8125rem; font-weight: 500; line-height: 1.5; letter-spacing: 0.1em; text-transform: uppercase; padding: 8px 0; text-decoration: none; color: var(--color-bone-2, #a5a29b); transition: color 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-rail__action.is-strong { font-weight: 600; color: var(--color-bone, #f2f0eb); }
.ds-rail__action:hover { color: var(--color-bone, #f2f0eb); }

.ds-channel { display: flex; align-items: center; gap: 4px; }
.ds-channel__opt { position: relative; font-family: 'Martian Mono', ui-monospace, 'Cascadia Mono', monospace; font-size: 0.625rem; font-weight: 500; line-height: 1.4; letter-spacing: 0.08em; text-transform: uppercase; font-variant-numeric: tabular-nums; padding: 14px 12px; border: none; background: none; cursor: pointer; color: var(--color-bone-3, #8a8782); transition: color 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-channel__opt.is-active { color: var(--color-bone, #f2f0eb); }
.ds-channel__opt:hover { color: var(--color-bone-2, #a5a29b); }
.ds-channel__rule { position: absolute; inset-inline: 10px; bottom: 10px; height: 1px; background: var(--color-rule, #2e2f33); transition: all 300ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-channel__opt.is-active .ds-channel__rule { height: 3px; background: var(--color-bone, #f2f0eb); }
.ds-channel__opt:focus-visible { outline: 1px solid var(--color-bone, #f2f0eb); outline-offset: 3px; }

.ds-row { border-top: 1px solid var(--color-rule, #2e2f33); border-bottom: 1px solid var(--color-rule, #2e2f33); padding: 40px 0; color: var(--color-bone-3, #8a8782); }
.ds-row__head { display: flex; align-items: baseline; justify-content: space-between; gap: 24px; }
.ds-row__title { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 125%; font-size: clamp(1.75rem, 5.2vw, 3.5rem); font-weight: 600; line-height: 1.02; letter-spacing: -0.035em; margin: 0; color: var(--color-bone, #f2f0eb); transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-row__year { font-family: 'Martian Mono', ui-monospace, 'Cascadia Mono', monospace; font-size: 0.625rem; font-weight: 500; line-height: 1.4; letter-spacing: 0.08em; text-transform: uppercase; font-variant-numeric: tabular-nums; flex-shrink: 0; color: var(--color-bone-3, #8a8782); }
.ds-row__trace { display: block; margin-top: 24px; height: 56px; width: 100%; color: var(--color-bone-3, #8a8782); transition: color 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-row__trace path { transition: stroke-width 500ms cubic-bezier(0.16, 1, 0.3, 1); }
.ds-row__body { margin-top: 32px; }
.ds-row__label { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: 0.8125rem; font-weight: 500; line-height: 1.5; letter-spacing: 0.1em; text-transform: uppercase; margin: 0; color: var(--color-bone-3, #8a8782); }
.ds-row__prose { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 100%; font-size: 1.0625rem; font-weight: 300; line-height: 1.65; max-width: 58ch; margin: 16px 0 0; color: var(--color-bone-2, #a5a29b); }
.ds-row:hover .ds-row__title { transform: translateX(8px); }
.ds-row:hover .ds-row__trace { color: var(--color-bone, #f2f0eb); }
.ds-row:hover .ds-row__trace path { stroke-width: 1.4; }

.ds-fields { border-top: 1px solid var(--color-rule, #2e2f33); margin: 0; }
.ds-fields__row { display: flex; gap: clamp(32px, 5vw, 64px); border-bottom: 1px solid var(--color-rule, #2e2f33); padding: 28px 0; }
.ds-fields__label { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: 0.8125rem; font-weight: 500; line-height: 1.5; letter-spacing: 0.1em; text-transform: uppercase; flex-shrink: 0; padding-top: 4px; width: clamp(132px, 16vw, 196px); color: var(--color-bone-3, #8a8782); }
.ds-fields__value { display: flex; flex-wrap: wrap; column-gap: 28px; row-gap: 10px; margin: 0; }
.ds-fields__value span { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 78%; font-size: clamp(1rem, 1.7vw, 1.25rem); font-weight: 500; letter-spacing: -0.005em; color: var(--color-bone, #f2f0eb); }

.ds-trace { position: relative; height: 140px; width: 100%; color: var(--color-bone, #f2f0eb); }
.ds-trace__baseline { position: absolute; inset-inline: 0; top: 50%; height: 1px; background: var(--color-grid, #1d1e22); }
.ds-trace__svg { position: absolute; inset: 0; height: 100%; width: 100%; overflow: visible; }
.ds-trace__pen { stroke-dasharray: 1 1; animation: ds-pen-draw 2.6s cubic-bezier(0.16, 1, 0.3, 1) 0.15s both; }
@keyframes ds-pen-draw { from { stroke-dashoffset: 1; } to { stroke-dashoffset: 0; } }
.ds-trace__pick { position: absolute; inset-block: 0; left: 52%; pointer-events: none; animation: ds-pick-in 0.42s cubic-bezier(0.16, 1, 0.3, 1) 1.1s both; }
@keyframes ds-pick-in { from { clip-path: inset(0 0 100% 0); } to { clip-path: inset(0 0 0 0); } }
.ds-trace__line { position: absolute; inset-block: 0; display: block; width: 1px; background: color-mix(in srgb, var(--color-bone-2, #a5a29b) 70%, transparent); }
.ds-trace__head { position: absolute; top: -1px; left: -3.5px; height: 7px; width: 8px; fill: var(--color-bone, #f2f0eb); }
.ds-trace__phase { position: absolute; top: 10px; left: 8px; font-family: 'Martian Mono', ui-monospace, 'Cascadia Mono', monospace; font-size: 0.625rem; font-weight: 500; line-height: 1.4; letter-spacing: 0.08em; text-transform: uppercase; font-variant-numeric: tabular-nums; color: var(--color-bone-2, #a5a29b); }
@media (prefers-reduced-motion: reduce) { .ds-trace__pen, .ds-trace__pick { animation-duration: 0.01ms; animation-delay: 0ms; } }

.ds-frame { margin: 0; width: 100%; max-width: 320px; }
.ds-frame__box { position: relative; aspect-ratio: 4 / 5; width: 100%; overflow: hidden; border: 1px solid var(--color-rule, #2e2f33); background: var(--color-ink, #08090a); }
.ds-frame__plate { height: 100%; width: 100%; filter: grayscale(1) contrast(1.08) brightness(0.92); background-image: repeating-linear-gradient(135deg, #2b2c30 0 6px, #1b1c20 6px 12px); }
.ds-frame__cap { font-family: 'Martian Mono', ui-monospace, 'Cascadia Mono', monospace; font-size: 0.625rem; font-weight: 500; line-height: 1.4; letter-spacing: 0.08em; text-transform: uppercase; font-variant-numeric: tabular-nums; margin-top: 12px; color: var(--color-bone-3, #8a8782); }

.ds-reg { color: var(--color-bone, #f2f0eb); }
.ds-reg__arrival { position: relative; height: 56px; }
.ds-reg__rule { position: absolute; inset-inline: 0; top: 50%; height: 1px; background: var(--color-rule, #2e2f33); }
.ds-reg__trace { position: absolute; inset: 0; height: 100%; width: 100%; color: var(--color-bone, #f2f0eb); overflow: visible; }
.ds-reg__head { margin-top: 24px; display: flex; align-items: baseline; gap: 32px; }
.ds-reg__num { font-family: 'Martian Mono', ui-monospace, 'Cascadia Mono', monospace; font-size: 0.625rem; font-weight: 500; line-height: 1.4; letter-spacing: 0.08em; text-transform: uppercase; font-variant-numeric: tabular-nums; flex-shrink: 0; color: var(--color-bone-3, #8a8782); }
.ds-reg__title { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 125%; font-size: clamp(1.75rem, 4.6vw, 3rem); font-weight: 600; line-height: 1.02; letter-spacing: -0.03em; margin: 0; color: var(--color-bone, #f2f0eb); }
.ds-reg__lead { font-family: 'Archivo Variable', ui-sans-serif, system-ui, sans-serif; font-stretch: 100%; font-size: clamp(1.0625rem, 1.5vw, 1.3125rem); font-weight: 300; line-height: 1.55; max-width: 62ch; margin: 24px 0 0; color: var(--color-bone-2, #a5a29b); }
